        {
          "kind": "formula",
          "value": "fml_dx_01"
        },
        {
          "kind": "text",
          "value": " come piccola variazione di "
        },
        {
          "kind": "formula",
          "value": "fml_x_01"
        },
        {
          "kind": "text",
          "value": " e "
        },
        {
          "kind": "formula",
          "value": "fml_dy_01"
        },
        {
          "kind": "text",
          "value": " come variazione stimata. Obiettivo esplicito: 'Alla fine, saprete stimare rapidamente le variazioni dovute a piccoli errori'."
        }
      ]
    },
