  "texts": [
    {
      "id": "txt-intro-q1",
      "segments": [
        {
          "kind": "text",
          "value": "Ieri abbiamo parlato di funzioni e del loro grafico. Guardate questi due grafici. Quale dei due potete disegnare senza mai staccare la penna dal foglio?"
        }
      ]
    },
    {
      "id": "txt-intro-obj",
      "segments": [
        {
          "kind": "text",
          "value": "Oggi dobbiamo capire cosa significa che una funzione è 'continua' e come riconoscere i punti in cui non lo è."
        }
      ]
    },
    {
      "id": "txt-intro-informal",
      "segments": [
        {
          "kind": "text",
          "value": "Immaginate di disegnare una funzione. Se non dovete mai alzare la penna dal foglio per disegnarla in un certo punto, allora la funzione è 'continua' in quel punto."
        }
      ]
    },
    {
      "id": "txt-continuity-def-title",
      "segments": [
        {
          "kind": "text",
          "value": "Definizione di funzione continua in un punto"
        }
      ]
    },
    {
      "id": "txt-continuity-def-intro",
      "segments": [
        {
          "kind": "text",
          "value": "Una funzione "
        },
        {
          "kind": "formula",
          "value": "f(x)"
        },
        {
          "kind": "text",
          "value": " è continua in un punto "
        },
        {
          "kind": "formula",
          "value": "x_0"
        },
        {
          "kind": "text",
          "value": " se valgono contemporaneamente tre condizioni:"
        }
      ]
    },
    {
      "id": "txt-cond1",
      "segments": [
        {
          "kind": "text",
          "value": "1. La funzione è definita in "
        },
        {
          "kind": "formula",
          "value": "x_0"
        },
        {
          "kind": "text",
          "value": ", cioè esiste "
        },
        {
          "kind": "formula",
          "value": "f(x_0)"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
      "id": "txt-cond2",
      "segments": [
        {
          "kind": "text",
          "value": "2. Esiste finito il limite della funzione per "
        },
        {
          "kind": "formula",
          "value": "x"
        },
        {
          "kind": "text",
          "value": " che tende a "
        },
        {
          "kind": "formula",
          "value": "x_0"
        },
        {
          "kind": "text",
          "value": ", cioè "
        },
        {
          "kind": "formula",
          "value": "\\lim_{x \\to x_0} f(x) = L"
        },
        {
          "kind": "text",
          "value": " con "
        },
        {
          "kind": "formula",
          "value": "L \\in \\mathbb{R}"
        },
        {
          "kind": "text",
          "value": "."
        }
      ]
    },
    {
