  "formulas": [
    {
      "id": "f_der_x3",
      "latex": "\\text{Se } F(x) = x^3 \\text{, allora } F'(x) = 3x^2",
      "alt_text": "Se F di x uguale x al cubo, allora F primo di x uguale 3x al quadrato",
      "expression": "F(x) = x^3 => F'(x) = 3x^2"
    },
    {
      "id": "f_int_ex_3x2",
      "latex": "\\text{Quindi } \\int 3x^2 dx = x^3 + C",
      "alt_text": "Quindi l'integrale di 3x al quadrato in dx uguale x al cubo più C",
      "expression": "integral(3x^2)dx = x^3 + C"
    },
    {
      "id": "f_int_def",
      "latex": "\\int f(x) dx = F(x) + C",
      "alt_text": "Integrale di f di x in dx uguale F maiuscolo di x più C",
      "expression": "integral(f(x))dx = F(x) + C"
    },
    {
      "id": "f_der_x",
      "latex": "f'(x) = x",
      "alt_text": "f primo di x uguale x",
      "expression": "f'(x) = x"
    },
    {
      "id": "f_int_2xplus3_q",
      "latex": "\\int (2x+3) dx",
      "alt_text": "Integrale di due x più tre in dx",
      "expression": "integral(2x+3)dx"
    },
    {
      "id": "f_int_2xplus3_step1",
      "latex": "\\int 2x dx + \\int 3 dx",
      "alt_text": "Integrale di due x in dx più integrale di tre in dx",
      "expression": "integral(2x)dx + integral(3)dx"
    },
    {
      "id": "f_int_2xplus3_step2",
      "latex": "2 \\int x dx + 3 \\int 1 dx",
      "alt_text": "Due volte integrale di x in dx più tre volte integrale di uno in dx",
      "expression": "2 * integral(x)dx + 3 * integral(1)dx"
    },
    {
      "id": "f_int_2xplus3_step3",
      "latex": "2 \\left(\\frac{x^2}{2}\\right) + 3x + C",
      "alt_text": "Due per x al quadrato fratto due più tre x più C",
      "expression": "2 * (x^2/2) + 3x + C"
    },
    {
      "id": "f_int_2xplus3_step4",
      "latex": "x^2 + 3x + C",
      "alt_text": "x al quadrato più tre x più C",
      "expression": "x^2 + 3x + C"
    },
    {
      "id": "f_int_power_rule",
      "latex": "\\int x^n dx = \\frac{x^{n+1}}{n+1} + C \\quad (n \\neq -1)",
      "alt_text": "Integrale di x alla n in dx uguale x alla n più uno fratto n più uno più C, per n diverso da meno uno",
      "expression": "integral(x^n)dx = x^(n+1)/(n+1) + C, n != -1"
    },
    {
      "id": "f_int_const_mult",
      "latex": "\\int k f(x) dx = k \\int f(x) dx",
      "alt_text": "Integrale di k per f di x in dx uguale k per integrale di f di x in dx",
      "expression": "integral(k * f(x))dx = k * integral(f(x))dx"
    },
    {
      "id": "f_int_sum_diff",
      "latex": "\\int [f(x) \\pm g(x)] dx = \\int f(x) dx \\pm \\int g(x) dx",
      "alt_text": "Integrale di f di x più o meno g di x in dx uguale integrale di f di x in dx più o meno integrale di g di x in dx",
      "expression": "integral(f(x) +/- g(x))dx = integral(f(x))dx +/- integral(g(x))dx"
    },
    {
      "id": "f_int_1_x",
      "latex": "\\int \\frac{1}{x} dx = \\ln|x| + C",
      "alt_text": "Integrale di uno fratto x in dx uguale logaritmo naturale del valore assoluto di x più C",
      "expression": "integral(1/x)dx = ln|x| + C"
    },
    {
      "id": "f_int_ex",
      "latex": "\\int e^x dx = e^x + C",
      "alt_text": "Integrale di e alla x in dx uguale e alla x più C",
      "expression": "integral(e^x)dx = e^x + C"
    },
    {
      "id": "f_int_cosx",
      "latex": "\\int \\cos x dx = \\sin x + C",
      "alt_text": "Integrale del coseno di x in dx uguale seno di x più C",
      "expression": "integral(cos x)dx = sin x + C"
    },
    {
      "id": "f_int_sinx",
      "latex": "\\int \\sin x dx = -\\cos x + C",
      "alt_text": "Integrale del seno di x in dx uguale meno coseno di x più C",
      "expression": "integral(sin x)dx = -cos x + C"
    },
    {
      "id": "f_int_polyn_ex_q",
      "latex": "\\int (3x^2 - 4x + e^x) dx",
      "alt_text": "Integrale di tre x al quadrato meno quattro x più e alla x in dx",
      "expression": "integral(3x^2 - 4x + e^x)dx"
    },
    {
      "id": "f_int_polyn_ex_s1",
      "latex": "= \\int 3x^2 dx - \\int 4x dx + \\int e^x dx",
      "alt_text": "uguale integrale di tre x al quadrato in dx meno integrale di quattro x in dx più integrale di e alla x in dx",
      "expression": "= integral(3x^2)dx - integral(4x)dx + integral(e^x)dx"
    },
    {
      "id": "f_int_polyn_ex_s2",
      "latex": "= 3 \\int x^2 dx - 4 \\int x dx + \\int e^x dx",
      "alt_text": "uguale tre volte integrale di x al quadrato in dx meno quattro volte integrale di x in dx più integrale di e alla x in dx",
      "expression": "= 3*integral(x^2)dx - 4*integral(x)dx + integral(e^x)dx"
    },
    {
      "id": "f_int_polyn_ex_final",
      "latex": "= x^3 - 2x^2 + e^x + C",
      "alt_text": "uguale x al cubo meno due x al quadrato più e alla x più C",
      "expression": "= x^3 - 2x^2 + e^x + C"
    },
    {
      "id": "f_int_x2_wrong",
      "latex": "\\int x^2 dx = \\frac{x^3}{3}",
