    {
      "id": "txt_costruzione_intro_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Durata: 18-28 min. Obiettivo: Introdurre il metodo di Cramer per i sistemi 3x3, passo dopo passo, con un esempio pratico. Il docente presenta un sistema lineare 3x3 da risolvere con Cramer."
        }
      ]
    },
    {
      "id": "txt_costruzione_step1_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 1: Calcoliamo il determinante dei coefficienti (D). Domanda: "
        },
        {
          "kind": "formula",
          "value": "Qual è la matrice D?"
        },
        {
          "kind": "text",
          "value": " Domanda: "
        },
        {
          "kind": "formula",
          "value": "Quanto vale D?"
        },
        {
          "kind": "text",
          "value": " (Risposta attesa: 2)."
        }
      ]
    },
    {
      "id": "txt_costruzione_step2_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 2: Calcoliamo i determinanti ausiliari "
        },
        {
          "kind": "formula",
          "value": "D_x, D_y, D_z"
        },
        {
          "kind": "text",
          "value": ". Domanda: "
        },
        {
          "kind": "formula",
          "value": "Come si forma D_x? Quanto vale D_x?"
        },
        {
          "kind": "text",
          "value": " (Risposta attesa: -2). Ripetere per "
        },
        {
          "kind": "formula",
          "value": "D_y"
        },
        {
          "kind": "text",
          "value": " (Risposta attesa: 4) e "
        },
        {
          "kind": "formula",
          "value": "D_z"
        },
        {
          "kind": "text",
          "value": " (Risposta attesa: 6)."
        }
      ]
    },
    {
      "id": "txt_costruzione_step3_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 3: Calcoliamo le incognite x, y, z usando le formule di Cramer. Domanda: "
        },
        {
          "kind": "formula",
          "value": "Come troviamo x, y, z?"
        },
        {
          "kind": "text",
          "value": " (Risposta attesa: "
        },
        {
          "kind": "formula",
          "value": "x = D_x/D"
        },
        {
          "kind": "text",
          "value": ", ecc.)."
        }
      ]
    },
    {
      "id": "txt_costruzione_step4_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 4: Scriviamo la soluzione."
        }
      ]
    },
    {
      "id": "txt_costruzione_result_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Soluzione attesa: "
        },
        {
          "kind": "formula",
          "value": "(x, y, z) = (-1, 2, 3)"
        }
      ]
    },
    {
      "id": "tg_sn4_costruzione",
      "segments": [
        {
          "kind": "text",
          "value": "Tempo: 10 minuti. Costruire un esempio guidato. Porre domande a bassa soglia ad ogni passaggio (es. 'Qual è il primo dato che ci serve?', 'Quale formula usiamo?'). Interrogare più studenti per diversi passaggi per mantenere alta la partecipazione. Usare il micro-confronto se una domanda è più complessa."
        }
      ]
    },
    {
      "id": "txt_costruzione_intro_sp",
      "segments": [
        {
          "kind": "text",
          "value": "Risolviamo un sistema 3x3 con il Metodo di Cramer."
        }
