    },
    {
      "id": "txt_costruzione_step1_sp",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 1: Calcolare il determinante D dei coefficienti."
        }
      ]
    },
    {
      "id": "txt_costruzione_step2_sp",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 2: Calcolare i determinanti ausiliari "
        },
        {
          "kind": "formula",
          "value": "D_x, D_y, D_z"
        },
        {
          "kind": "text",
          "value": "."
        }
