    {
      "id": "txt_costruzione_step3_sp",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 3: Calcolare le incognite "
        },
        {
          "kind": "formula",
          "value": "x, y, z"
        },
        {
          "kind": "text",
          "value": " usando le formule:"
        }
      ]
    },
    {
      "id": "txt_costruzione_step4_sp",
      "segments": [
        {
          "kind": "text",
          "value": "Passo 4: La soluzione è la terna "
