    {
      "id": "txt_costruzione_result_sp",
      "segments": [
        {
          "kind": "text",
          "value": "La soluzione è: "
        },
        {
          "kind": "formula",
          "value": "(x, y, z) = (-1, 2, 3)"
        }
      ]
    },
    {
      "id": "txt_microl2_intro_tg",
      "segments": [
        {
          "kind": "text",
          "value": "Durata: 28-35 min. Obiettivo: Formalizzare il metodo di Cramer. Il docente riepiloga le formule e il procedimento standard, chiarendo il caso D=0."
