      "expression": "(-(-5) + sqrt(1)) / (2*1)"
    },
    {
      "id": "formula_ex02_x1",
      "latex": "x_1 = \\frac{5 - 1}{2} = 2",
      "alt_text": "x uno uguale a 5 meno 1 fratto 2 uguale 2",
      "expression": "(5 - 1) / 2"
    },
    {
      "id": "formula_ex02_x2",
      "latex": "x_2 = \\frac{5 + 1}{2} = 3",
      "alt_text": "x due uguale a 5 più 1 fratto 2 uguale 3",
      "expression": "(5 + 1) / 2"
