    },
    {
      "id": "formula_ex03_eq_sviluppata",
      "latex": "x^2 + 2x - 48 = 0",
      "alt_text": "equazione x al quadrato più 2x meno 48 uguale 0",
      "expression": "x**2 + 2*x - 48 = 0"
    },
